'use strict';
const $=id=>document.getElementById(id),E=t=>String(t??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state=SP.defaults(),saveOK=true,retiredRaw=null,retiredNeedsProtection=false;const thumbs=new Map();try{retiredRaw=localStorage.getItem('shotprompt2.retired-writing-backup');const raw=localStorage.getItem('shotprompt2.project');if(raw){const saved=JSON.parse(raw);if(['script','storyboard'].includes(saved.type)||Object.prototype.hasOwnProperty.call(saved,'script')||Object.prototype.hasOwnProperty.call(saved,'frames')){retiredRaw=raw;try{localStorage.setItem('shotprompt2.retired-writing-backup',raw);}catch(e){retiredNeedsProtection=true;setTimeout(()=>toast('Browser storage is full. Download your archived project; its autosave is protected.'),100);}if(!['script','storyboard'].includes(saved.type))state=SP.validate(saved);}else state=SP.validate(saved);}}catch(e){setTimeout(()=>toast('Saved project could not load. You can open a project backup.'),100);}
function toast(t){$('toast').textContent=t;$('toast').className='on';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').className='',3200);}
function persist(){if(retiredNeedsProtection)return;try{localStorage.setItem('shotprompt2.project',JSON.stringify(state));saveOK=true;}catch(e){if(saveOK)toast('Browser storage is unavailable. Use Save project to keep your work.');saveOK=false;}}
function icon(shot='medium',move='static',view='Front'){
const person=shot==='close'?'<circle cx="80" cy="38" r="24"/><path d="M35 110 Q37 65 80 65 Q123 65 125 110"/>':shot==='detail'?'<path d="M48 39h51v39H48z M100 45q28 0 15 21H100 M40 84h73"/>':shot==='wide'?'<circle cx="80" cy="40" r="9"/><path d="M67 79V60q13-18 26 0v19 M72 79v19 M88 79v19 M10 85h140 M17 12v53h31V12z"/>':'<circle cx="80" cy="34" r="15"/><path d="M54 100V75q1-25 26-25t26 25v25 M57 79h46"/>';
const arrow={static:'<path d="M12 20V10h12 M136 10h12v10 M148 90v10h-12 M24 100H12V90"/>',push:'<path d="M30 86L56 62m-15 2 15-2-2 15 M130 86l-26-24m2 15-2-15 15 2"/>',pan:'<path d="M25 20h105m-12-9 12 9-12 9"/>',track:'<path d="M25 91h105m-12-9 12 9-12 9"/>',orbit:'<path d="M27 68c-24 40 130 40 107 0m-11 4 11-4 4 12"/>',pull:'<path d="M57 62L30 86m0-14v14h14 M103 62l27 24m-14 0h14V72"/>',tilt:'<path d="M135 85V20m-9 12 9-12 9 12"/>',crane:'<path d="M23 85V20m-9 12 9-12 9 12 M15 85h30"/>',handheld:'<path d="M20 80l9-8-6-12 10-8-4-10 M132 25l-8 10 5 12-8 10"/>',zoom:'<circle cx="126" cy="80" r="12"/><path d="M135 89l13 13 M120 80h12 M126 74v12"/>'}[move];
const face=view==='Left profile'?'<path d="M70 24l-10 13 10 5 M74 30h1"/>':view==='Right profile'?'<path d="M90 24l10 13-10 5 M86 30h1"/>':view==='Back'?'':'<path d="M74 32h1m10 0h1M76 40h8"/>';
return '<svg viewBox="0 0 160 110" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2.3" stroke-linecap="round" stroke-linejoin="round">'+person+face+arrow+'</svg>';
}
const field=(label,key,value,area=false,ph='')=>'<div class="field"><label for="f-'+key+'">'+label+'</label><'+(area?'textarea':'input')+' id="f-'+key+'" data-key="'+key+'" placeholder="'+E(ph)+'"'+(area?'': ' value="'+E(value)+'"')+'>'+(area?E(value)+'</textarea>':'')+'</div>';
function options(a,val){return a.map(([v,l])=>'<option value="'+E(v)+'"'+(v===val?' selected':'')+'>'+E(l)+'</option>').join('');}
function sel(label,key,items,val){return '<div><label for="f-'+key+'">'+label+'</label><select id="f-'+key+'" data-key="'+key+'">'+options(items,val)+'</select></div>';}
function pills(key,dict){return '<div class="pills" role="group" aria-label="'+key+'">'+Object.entries(dict).map(([k,v])=>'<button data-pick="'+key+'" data-value="'+k+'" aria-pressed="'+(state[key]===k)+'">'+E(v)+'</button>').join('')+'</div>';}
function framing(){return '<div class="block"><h2>How close should it feel?</h2><div class="choices" role="group" aria-label="Shot framing">'+Object.entries(SP.shots).map(([k,v])=>'<button data-pick="shot" data-value="'+k+'" aria-pressed="'+(state.shot===k)+'">'+framingSketch(k)+'<strong>'+({wide:'Show the setting',medium:'Show the subject',close:'Move in close',detail:'One small detail'}[k])+'</strong><small>'+({wide:'Wide shot',medium:'Medium shot',close:'Close-up',detail:'Detail shot'}[k])+'</small></button>').join('')+'</div></div>';}
function movements(){return '<div class="block"><h2>What does the camera do?</h2><p class="hint">The camera can stay still while your subject moves.</p><div class="choices" role="group" aria-label="Camera motion">'+Object.entries(SP.moves).filter(([k])=>state.advanced||['static','push','pull','pan','track','orbit'].includes(k)||state.move===k).map(([k,v])=>'<button data-pick="move" data-value="'+k+'" aria-pressed="'+(state.move===k)+'">'+icon('medium',k)+'<strong>'+v[0]+'</strong><small>'+({static:'Static · fixed frame',push:'Dolly in · physical move',pan:'Pan right · turn in place',track:'Tracking · move alongside',orbit:'Orbit · circle the subject',pull:'Dolly out · physical move',tilt:'Tilt · turn vertically',crane:'Crane · move vertically',handheld:'Handheld · organic drift',zoom:'Zoom · change focal length'}[k])+'</small></button>').join('')+'</div></div>';}
const expandedRefs=new WeakSet();if(state.refs[0])expandedRefs.add(state.refs[0]);
function refTitle(r,i){return (r.kind==='element'?'Element':SP.refName(state,i))+' · '+(r.name.trim()||'Unnamed reference')+' · '+r.role;}
function refs(){return '<div class="block" id="references" tabindex="-1"><h2>Bring your references</h2><p class="hint">'+(state.type==='image'&&state.task==='edit'?'Required: map the base image to edit first. ':state.type==='video'&&state.videoTask!=='new'?'Required: map exactly one source video. ':'Optional: map what each reference controls. ')+'Attach media separately in your generation app. Local previews do not upload anything.</p>'+state.refs.map((r,i)=>'<details class="reference" data-ref-card="'+i+'"'+(expandedRefs.has(r)?' open':'')+'><summary><span data-ref-title="'+i+'">'+E(refTitle(r,i))+'</span><small>Tap to edit reference</small></summary><div class="reference-body">'+(thumbs.has(i)?'<img class="thumbnail" src="'+thumbs.get(i)+'" alt="Reference '+(i+1)+' preview">':'')+'<div class="frame-head"><h3>Reference '+(i+1)+' · '+E(r.kind==='element'?'Element':SP.refName(state,i))+'</h3><div class="ref-actions"><button data-ref-shift="'+i+'" data-direction="-1" aria-label="Move reference '+(i+1)+' earlier"'+(i===0?' disabled':'')+'>Earlier</button><button data-ref-shift="'+i+'" data-direction="1" aria-label="Move reference '+(i+1)+' later"'+(i===state.refs.length-1?' disabled':'')+'>Later</button><button data-remove-ref="'+i+'">Remove</button></div></div>'+(state.type==='image'&&state.task==='edit'&&i===state.refs.findIndex(x=>x.kind==='image')?'<p class="base-image-note">Base image to edit · '+E(SP.refName(state,i))+'</p>':'')+'<div class="row">'+refSel(i,'kind','Reference type',[['image','Uploaded image'],['element','Saved element / mention'],['video','Source video']],r.kind)+refSel(i,'role','Use it for',[['source','Edit target / source'],['identity','Identity'],['outfit','Outfit'],['location','Location'],['composition','Composition'],['product','Product'],['style','Style']],r.role)+'</div><p class="hint">'+E(r.kind==='image'&&state.type==='image'&&state.task==='edit'&&i===state.refs.findIndex(x=>x.kind==='image')?'This image is the edit target. Move a different image ahead of it to change the target.':r.kind==='video'?'This source controls video continuity.':SP.roleRules[r.role])+'</p><label for="r-'+i+'-name">Who or what is it?</label><input id="r-'+i+'-name" data-ref="'+i+'" data-ref-key="name" value="'+E(r.name)+'" placeholder="e.g. Maya"><div class="field">'+(r.kind==='video'?'<p class="hint">Upload this video separately as '+E(SP.refName(state,i))+' in your generation app. No video is uploaded from ShotPrompt.</p>':r.kind==='element'?'<label for="r-'+i+'-token">Exact Element mention token</label><input id="r-'+i+'-token" data-ref="'+i+'" data-ref-key="token" value="'+E(r.token)+'" placeholder="Paste the token shown in your generation app">':'<label for="preview-'+i+'">Local image preview (optional)</label><input type="file" id="preview-'+i+'" accept="image/png,image/jpeg,image/webp" data-preview="'+i+'">')+'</div></div></details>').join('')+'<button id="add-ref"'+(state.refs.length>=20?' disabled':'')+'>Add a reference</button><p class="hint">Element tokens are copied exactly as entered. A typed token does not upload or bind an Element automatically.</p></div>';}
function refSel(i,key,label,items,val){return '<div><label for="r-'+i+'-'+key+'">'+label+'</label><select id="r-'+i+'-'+key+'" data-ref="'+i+'" data-ref-key="'+key+'">'+options(items,val)+'</select></div>';}

function sceneSketch(key){const paths={general:'M12 50h76V12H12z M25 38l16-16 15 14 10-7 12 13',people:'M50 11a10 10 0 1 0 0 20a10 10 0 1 0 0-20 M30 55V45q20-22 40 0v10',landscape:'M5 53l26-35 17 21 15-28 32 42z M16 41h12 M68 18h4',product:'M38 17h24v36H38z M43 8h14v9 M31 55h38 M42 30h16',architecture:'M12 55V22l38-12 38 12v33 M28 55V31h16v24 M57 30h17v13',food:'M18 34q0 24 32 24t32-24z M12 34h76 M37 10q-8 6 0 13 M52 8q-8 6 0 13 M67 10q-8 6 0 13',abstract:'M20 17h34v34H20z M61 10a22 22 0 1 0 0 44a22 22 0 1 0 0-44',vfx:'M50 5l7 20 22-5-15 17 15 18-22-6-7 17-7-19-22 5 14-16-14-16 22 5z'};return '<svg viewBox="0 0 100 70" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2" stroke-linejoin="round">'+(key==='look'?'<path d="M5 57l25-30 20 20 15-32 30 42z"/><circle cx="28" cy="13" r="6"/><path d="M5 62h90"/>':'<path d="'+paths[key]+'"/>')+'</svg>';}
function framingSketch(shot){if(['general','people'].includes(state.category))return icon(shot);return '<span class="shot-scene shot-'+shot+'">'+sceneSketch(state.category)+'</span>';}
function sceneChoices(){return '<div class="block"><h2>What kind of scene?</h2><p class="hint">Choose a starting point. Your description stays yours.</p><div class="scene-choices" role="group" aria-label="Scene category">'+Object.entries(SP.categories).map(([k,v])=>'<button data-pick="category" data-value="'+k+'" aria-pressed="'+(state.category===k)+'">'+sceneSketch(k)+'<strong>'+E(v[0])+'</strong><small>'+E(v[1])+'</small></button>').join('')+'</div></div>';}
function sceneFields(){const fields=SP.categoryFields[state.category];return fields.length?'<div class="block"><h2>'+E(SP.categories[state.category][0])+' details</h2>'+fields.map(([k,label,ph])=>field(label,k,state[k],true,ph)).join('')+'</div>':'';}
function renderingChoices(){
const family=['render','anime','illustration'].includes(state.style);
if(!family)return state.renderStyle!=='auto'?'<p class="help">Saved rendering detail: '+E(SPCinema.options.renderStyle[state.renderStyle][0])+'. <button type="button" data-pick="style" data-value="'+(['watercolor','ink','halftone','collage'].includes(state.renderStyle)?'illustration':'render')+'">Show style options</button></p>':'';
const groups=state.style==='render'?['realcg','toon','paint3d','clay','miniature','lowpoly','retro']:state.style==='anime'?['toon','paint3d','watercolor','ink','halftone']:['watercolor','ink','halftone','collage'];
if(state.renderStyle!=='auto'&&!groups.includes(state.renderStyle))groups.push(state.renderStyle);
return '<div class="rendering-options"><h3>'+E(state.style==='render'?'3D':state.style==='anime'?'Anime':'Illustration')+' rendering style</h3>'+sel('Rendering style','renderStyle',[['auto','Default for this look'],...groups.map(k=>[k,SPCinema.options.renderStyle[k][0]])],state.renderStyle)+'<p class="hint">Refines the selected look. Changing the main look resets this detail.</p></div>';
}
function lookChoices(){return '<div class="look-choices" role="group" aria-label="Visual style">'+Object.entries(SP.styleLabels).filter(([k])=>state.advanced||['natural','cinema','photo','commercial','illustration','render','anime'].includes(k)||state.style===k).map(([k,label])=>'<button data-pick="style" data-value="'+k+'" aria-pressed="'+(state.style===k)+'"><span class="look-sample look-'+k+'">'+sceneSketch('look')+'</span><strong>'+E(label)+'</strong></button>').join('')+'</div>'+renderingChoices()+'<p class="hint">Choose a look, then refine its style. Advanced reveals additional photographic looks.</p>';}
function cameraSelect(label,key){return sel(label,key,Object.entries(SP.cameraOptions[key]).map(([k,v])=>[k,v[0]]),state[key]);}
function creativeAdvanced(){if(!SP.isCreative(state))return '';return '<h3>Camera and composition</h3><div class="row">'+cameraSelect('Camera angle','angle')+cameraSelect('Lens feel','lens')+'</div><div class="row">'+cameraSelect('Depth of field','focus')+cameraSelect('Composition','composition')+'</div><p class="hint">Lens values describe a visual feel. They do not set camera hardware or destination-app parameters.</p>'+(state.type==='video'&&!SPTiming.active(state)&&state.move!=='static'?'<div class="row">'+cameraSelect('Movement speed','speed')+sel('Movement direction','direction',Object.entries(SP.directions(state.move)),state.direction)+'</div>':'')+(state.effect!=='none'?'<div class="row">'+cameraSelect('Effect intensity','intensity')+(state.type==='video'?cameraSelect('When the effect appears','timing'):'')+'</div>':'')+'<hr>';}
function effects(){if(!SP.isCreative(state))return '';return '<div class="block"><h2>Effects in the scene</h2><p class="hint">Independent of camera motion. Leave None for a clean scene.</p>'+cameraSelect('Visual effect','effect')+(state.effect!=='none'&&state.category!=='vfx'?field('Effect placement and interaction','effectNotes',state.effectNotes,true,'Where does it appear? For transformations, describe the starting and final forms.'):'')+'<p class="hint">These are written visual directions; model support and results vary.</p></div>';}
const sceneExamples={general:['A ceramic cup on a wooden table.','The cup remains still.','Quiet room tone; no music.'],people:['An adult sitting by a café window, looking outside.','The person turns gently toward the window.','Quiet café room tone; no music.'],landscape:['A remote alpine lake beneath steep mountains.','Small ripples cross the lake as clouds drift.','Wind and gentle water; no speech or music.'],product:['One unbranded perfume bottle on a matte stone plinth.','The bottle remains stationary; highlights move naturally with the camera.','Quiet studio ambience; no music.'],architecture:['A sunlit courtyard with curved concrete walls and an olive tree.','Leaves stir in a gentle breeze.','Leaves rustling and distant outdoor ambience.'],food:['A bowl of fresh noodles on a handmade ceramic plate.','A faint ribbon of steam rises from the food.','Quiet dining room ambience; no music.'],abstract:['Translucent folded glass forms against a muted blue background.','The glass forms rotate slowly in place.','A soft ambient hum; no speech.'],vfx:['A cyclist crossing a rain-soaked street at night.','The cyclist rides across frame while sparks trail behind the rear wheel.','Rain and bicycle tire noise; no speech.']};


let presetChoice=null,presetUndo=null,guideTopic='framing',guideOpen=false;
function clearPresetUndo(){presetUndo=null;const button=$('undo-preset');if(button)button.hidden=true;}
function startingPoints(){return '<details class="starting-points"><summary>Start with a guided preset <small>Five editable starting points</small></summary><p class="hint">Preview the choices before applying. Your references and edited prompt are kept.</p><div class="preset-grid">'+Object.entries(SPGuide.presets).map(([id,p])=>'<button type="button" data-preview-preset="'+id+'">'+sceneSketch(p.category)+'<strong>'+E(p.name)+'</strong><small>'+E(p.description)+'</small></button>').join('')+'</div></details><button id="undo-preset" class="undo-preset"'+(presetUndo?'':' hidden')+'>Undo preset</button>';}
function visualGuide(){return '<details id="visual-guide" class="visual-guide"'+(guideOpen?' open':'')+'><summary>See what these choices mean <small>Framing, lenses, movement & effects</small></summary><div class="guide-tabs" role="group" aria-label="Visual explanation">'+[['framing','Framing'],['lens','Lenses'],['motion','Movement'],['effects','Effects']].map(([id,name])=>'<button type="button" data-guide-topic="'+id+'" aria-pressed="'+(id===guideTopic)+'">'+name+'</button>').join('')+'</div><div id="guide-content">'+guideContent()+'</div></details>';}
function guideContent(){const t=SPGuide.text[guideTopic];return '<h3>'+t.title+'</h3><div class="guide-diagrams">'+t.labels.map((label,i)=>'<figure>'+SPGuide.diagram(guideTopic,i)+'<figcaption>'+label+'</figcaption></figure>').join('')+'</div><p>'+t.body+'</p><small class="hint">Illustrated explanation, not a generated result.</small>';}
function previewPreset(id){presetChoice=id;const p=SPGuide.presets[id],next=SPGuide.apply(state,id);const labels={idea:'Scene description',category:'Scene category',shot:'Framing',style:'Look',light:'Light',angle:'Camera angle',lens:'Lens feel',focus:'Depth of field',composition:'Composition',move:'Camera movement',speed:'Movement speed',effect:'Visual effect',intensity:'Effect intensity',timing:'Effect timing',direction:'Movement direction'};
function value(k,v){if(k==='category')return SP.categories[v][0];if(k==='style')return SP.styleLabels[v];if(SP.cameraOptions[k])return SP.cameraOptions[k][v][0];if(k==='shot')return ({wide:'Wide',medium:'Medium',close:'Close-up',detail:'Detail'})[v];if(k==='move')return SP.moves[v][0];return String(v);}
const changed=Object.keys(next).filter(k=>JSON.stringify(next[k])!==JSON.stringify(state[k])&&!['draft','refs'].includes(k));
$('preset-content').innerHTML='<h2 id="preset-title">'+E(p.name)+'</h2><p>'+E(p.description)+'</p><p class="help">Applies to this '+(state.type==='video'?'video':'image')+' builder. References, model, aspect ratio, duration, extra instructions and exclusions are kept.'+(state.draft!==null?' Your edited output stays unchanged until you choose Use updated builder.':'')+'</p><h3>Choices this will replace</h3>'+(changed.length?'<dl class="preset-changes">'+changed.map(k=>'<div><dt>'+E(labels[k]||k.replace(/([A-Z])/g,' $1'))+'</dt><dd>'+E(value(k,next[k]))+(next[k]===''?'Cleared':'')+'</dd></div>').join('')+'</dl>':'<p>These choices already match your builder.</p>')+'<p class="hint">All choices remain editable. Camera movement, action and sound apply only to new videos. Presets do not clear your extra instructions; review any conflicting wording.</p>';
$('preset-dialog').showModal();}


let editPresetChoice=null;
function editStartingPoints(){return '<details class="starting-points edit-starts"><summary>Start with an editing example <small>Preview first; then adapt it to your source</small></summary><div class="preset-grid">'+SPEdit.available(state).map(([id,p])=>'<button type="button" data-edit-preset="'+id+'"><strong>'+E(p.name)+'</strong><small>'+E(p.change||p.action)+'</small></button>').join('')+'</div></details><button id="undo-preset" class="undo-preset"'+(presetUndo?'':' hidden')+'>Undo preset</button>';}
function editFields(){return '<div class="edit-pair"><div class="edit-change"><span class="edit-step">CHANGE</span>'+field('What should change?','editChange',state.editChange,true,'Describe only the changes you want.')+'<p class="hint">Name the object or area and the new result. Everything else should remain consistent.</p></div><div class="edit-keep"><span class="edit-step">KEEP</span>'+field('What must stay the same?','editKeep',state.editKeep,true,'List the details the edit must preserve.')+'<p class="hint">For example: identity, pose, outfit, product details, framing or sound. Do not lock a detail you are changing.</p></div></div>';}
function previewEdit(id){editPresetChoice=id;presetChoice=null;const p=SPEdit.presets[id];$('preset-content').innerHTML='<h2 id="preset-title">'+E(p.name)+'</h2><p>This is an editable example, not an analysis of your source. Replace the example details to match your image or video.</p><h3>'+(p.action?'What happens next':'Change')+'</h3><p>'+E(p.action||p.change)+'</p>'+(!p.action?'<h3>Keep</h3><p>'+E(p.keep)+'</p>':'')+'<p class="help">Only '+(p.action?'the continuation action':'the Change and Keep fields')+' will be replaced.'+(p.action&&SPTiming.active(state)?' Timing will switch to Whole clip; your saved segments are retained.':'')+' Your source references, model, duration, extra instructions and manually edited output are kept.</p>';$('preset-dialog').showModal();}
function renderEditSummary(){const v=SPEdit.summary(state),box=$('edit-summary');box.hidden=!v;if(!v)return;box.innerHTML='<h3>Before you copy · '+E(v.operation)+'</h3>'+(v.manual?'<p class="edit-manual">Builder summary only. Your edited output is kept and may differ. Use updated builder only when you want to replace it.</p>':'')+'<dl><dt>Source</dt><dd>'+E(v.source||'Not mapped yet — add the source reference.')+(v.multiple?' · More than one video is mapped; choose exactly one.':'')+'</dd><dt>'+(state.type==='video'&&state.videoTask==='extend'?'Next action':'Change')+'</dt><dd>'+E(state.type==='video'&&state.videoTask==='extend'&&SPTiming.active(state)?'See the timed continuation segments above.':v.change||'Describe your change.')+'</dd><dt>Keep</dt><dd>'+E(v.keep||'List the details to preserve.')+'</dd></dl><p class="hint">'+E(v.inherit)+'</p><div class="mini-actions"><button type="button" data-review-field="refs">Review source</button><button type="button" data-review-field="'+(state.type==='video'&&state.videoTask==='extend'?'action':'editChange')+'">Review instructions</button></div>';}


function beatSelect(i,key,label,items){return '<div><label for="beat-'+i+'-'+key+'">'+label+'</label><select id="beat-'+i+'-'+key+'" data-beat="'+i+'" data-beat-key="'+key+'">'+options(items,state.beats[i][key])+'</select></div>';}
function timingControls(){if(state.type!=='video'||state.videoTask==='edit')return '';const extension=state.videoTask==='extend',on=SPTiming.active(state);
return '<div class="block timing-controls" id="timing-controls" tabindex="-1"><h2>Timing &amp; shots</h2><p class="hint">'+(extension?'Times start at 0 seconds of the new extension. The source camera trajectory is preserved.':'Choose one continuous take or a sequence of shots. Timing guides generation; it does not edit existing footage.')+'</p><div class="pills" role="group" aria-label="Timing mode">'+[['off','Whole clip'],['continuous','Timed continuous'],...(!extension?[['multi','Multiple shots']]:[])].map(([key,label])=>'<button type="button" data-timing-mode="'+key+'" aria-pressed="'+(state.timelineMode===key)+'">'+label+'</button>').join('')+'</div>'+(extension&&state.timelineMode==='multi'?'<p class="help">Saved multi-shot settings are not emitted for extensions. Choose Timed continuous to plan the new portion.</p>':'')+(on?(!extension?'<label for="duration">Total clip length in seconds</label><input id="duration" data-key="duration" type="number" min="1" max="300" step="1" value="'+state.duration+'">'+sel('Image shape','ratio',['16:9','9:16','1:1','4:3','3:4'].map(x=>[x,x]),state.ratio):'')+'<p class="hint" id="timing-range-hint">Use adjoining ranges from 0 to '+state.duration+' seconds. Fit to duration redistributes the ranges evenly and keeps your descriptions.</p><div class="timing-strip" aria-label="Timing overview">'+state.beats.map((b,i)=>'<span>'+ (i+1)+' · '+E(b.start)+'–'+E(b.end)+'s</span>').join('')+'</div>'+state.beats.map((b,i)=>'<section class="beat-card"><div class="frame-head"><h3>'+(state.timelineMode==='multi'?'Shot ':'Segment ')+(i+1)+'</h3><div class="ref-actions"><button type="button" data-beat-shift="'+i+'" data-direction="-1"'+(!i?' disabled':'')+' aria-label="Move segment '+(i+1)+' earlier">Earlier</button><button type="button" data-beat-remove="'+i+'" aria-label="Remove segment '+(i+1)+'">Remove</button></div></div><div class="row"><div><label for="beat-'+i+'-start">Start · seconds</label><input id="beat-'+i+'-start" type="number" min="0" max="300" step="0.1" data-beat="'+i+'" data-beat-key="start" value="'+b.start+'"></div><div><label for="beat-'+i+'-end">End · seconds</label><input id="beat-'+i+'-end" type="number" min="0" max="300" step="0.1" data-beat="'+i+'" data-beat-key="end" value="'+b.end+'"></div></div><label for="beat-'+i+'-action">What happens?</label><textarea id="beat-'+i+'-action" data-beat="'+i+'" data-beat-key="action" placeholder="Describe the visible action, reaction or pause…">'+E(b.action)+'</textarea>'+(!extension?(state.advanced?'<div class="row">'+beatSelect(i,'coverage','Conversation coverage',[['inherit','Use default coverage'],...Object.entries(SPCinema.options.coverage).map(([k,v])=>[k,v[0]])])+'</div>':'')+'<div class="row">'+beatSelect(i,'shot','Framing',Object.keys(SP.shots).map(k=>[k,({wide:'Wide',medium:'Medium',close:'Close-up',detail:'Detail'})[k]]))+beatSelect(i,'move','Camera movement',Object.entries(SP.moves).map(([k,v])=>[k,v[0]]))+'</div>'+(state.advanced?'<div class="row">'+beatSelect(i,'angle','Camera angle',[['inherit','Use default angle'],...Object.entries(SP.cameraOptions.angle).map(([k,v])=>[k,v[0]])])+beatSelect(i,'composition','Composition',[['inherit','Use default composition'],...Object.entries(SP.cameraOptions.composition).map(([k,v])=>[k,v[0]])])+'</div><div class="row">'+beatSelect(i,'speed','Movement speed',Object.entries(SP.cameraOptions.speed).map(([k,v])=>[k,v[0]]))+beatSelect(i,'direction','Direction',Object.entries(SP.directions(b.move)))+'</div>':'<p class="hint">Advanced adds per-segment speed and direction.</p>')+(state.timelineMode==='multi'&&i?beatSelect(i,'transition','Entry transition',[['cut','Hard cut'],['dissolve','Cross-dissolve'],['continue','Seamless continuation']]):''):'')+'</section>').join('')+'<div class="mini-actions"><button id="add-beat" type="button"'+(state.beats.length>=12?' disabled':'')+'>Add segment</button><button id="fit-beats" type="button"'+(!state.beats.length?' disabled':'')+'>Fit to duration</button></div>':'')+'</div>';}
function renderTimingHandoff(){const strip=document.querySelector('#timing-controls .timing-strip');if(strip)strip.innerHTML=state.beats.map((b,i)=>'<span>'+(i+1)+' · '+E(b.start)+'–'+E(b.end)+'s</span>').join('');if($('timing-range-hint'))$('timing-range-hint').textContent='Use adjoining ranges from 0 to '+state.duration+' seconds. Fit to duration redistributes ranges evenly and keeps your descriptions.';const d=SPTiming.handoff(state),box=$('timing-handoff');box.hidden=!d;if(!d)return;box.innerHTML='<h3>'+(state.draft!==null?'Builder timing plan':'Timing plan & destination setup')+'</h3><div class="timing-strip">'+d.rows.map(r=>'<span>'+E(r.label)+' · '+E(r.range)+' · '+E(r.duration)+'</span>').join('')+'</div><ul>'+d.notes.map(n=>'<li>'+E(n)+'</li>').join('')+'</ul>'+(d.source?'<a href="'+d.source[1]+'" target="_blank" rel="noopener noreferrer">'+E(d.source[0])+'</a>':'');}


let cinemaOpen=false,cinemaPresetChoice=null;
function cinemaSelect(label,key){return sel(label,key,Object.entries(SPCinema.options[key]).map(([k,v])=>[k,v[0]]),state[key]);}
function coverageDiagram(key){const flip=['otsb','singleb','reactionb','povb'].includes(key),ots=key.startsWith('ots'),single=key.startsWith('single')||key.startsWith('reaction'),pov=key.startsWith('pov');return '<svg viewBox="0 0 180 100" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2"><path d="M8 90h164" opacity=".35"/>'+ (ots?'<g'+(flip?' transform="translate(180 0) scale(-1 1)"':'')+'><path d="M0 98V58q24-20 45 0l13 40" fill="currentColor" opacity=".35"/><circle cx="20" cy="39" r="19" fill="currentColor" opacity=".35"/><circle cx="122" cy="37" r="14"/><path d="M94 85V67q28-27 56 0v18 M113 35h2m13 0h2"/><text x="14" y="43" stroke="none" fill="currentColor" font-size="11">'+(flip?'B':'A')+'</text><text x="118" y="74" stroke="none" fill="currentColor" font-size="12">'+(flip?'A':'B')+'</text></g>':single||pov?'<circle cx="90" cy="36" r="19"/><path d="M51 89V72q39-33 78 0v17"/><text x="85" y="76" stroke="none" fill="currentColor" font-size="12">'+(pov?(flip?'A':'B'):(flip?'B':'A'))+'</text><path d="M'+(flip?'64 35h-24m8-5-8 5 8 5':'116 35h24m-8-5 8 5-8 5')+'"/>'+ (pov?'<path d="M5 18V5h18 M157 5h18v13"/>':''):'<circle cx="49" cy="37" r="15"/><circle cx="131" cy="37" r="15"/><path d="M22 87V68q27-25 54 0v19 M104 87V68q27-25 54 0v19 M70 35h40"/><text x="44" y="77" stroke="none" fill="currentColor" font-size="12">A</text><text x="126" y="77" stroke="none" fill="currentColor" font-size="12">B</text>')+'</svg>';}
function renderSample(key){const attrs=key==='ink'||key==='halftone'?'fill="none" stroke-width="2"':key==='clay'?'fill="#bd937c" stroke-width="3"':key==='toon'?'fill="#baa5d1" stroke-width="3"':'fill="#a4b69b" stroke-width="1.5"';return '<svg viewBox="0 0 180 90" aria-hidden="true" stroke="currentColor"><ellipse cx="90" cy="77" rx="62" ry="7" fill="currentColor" opacity=".12"/><path d="M33 34l35-16 31 19v36L64 83 33 66z" '+attrs+'/><circle cx="123" cy="49" r="27" '+attrs+'/>'+(key==='paint3d'||key==='ink'?'<path d="M105 35l30 22m-35-9 29 20m-81-26 23 15m-28 1 22 14" fill="none" stroke-width="3" opacity=".5"/>':key==='toon'?'<path d="M126 22q-35 27 0 54" fill="none" stroke-width="8" opacity=".35"/>':key==='clay'?'<path d="M110 37q12-6 22 0 M48 45l14 8" fill="none" stroke-width="3" opacity=".35"/>':'')+'</svg>';}
function cinemaControls(){if(!SP.isCreative(state)||!state.advanced)return '';const timed=SPTiming.active(state);return '<details id="cinema-controls" class="visual-guide"'+(cinemaOpen?' open':'')+'><summary>Composition &amp; conversation <small>OTS, eyelines, unusual viewpoints and visual rules</small></summary><h3>'+ (timed?'Default conversation coverage':'Conversation coverage')+'</h3><p class="hint">A and B are two subject labels. OTS means over the shoulder. '+(timed?'Each timed shot can override this default below.':'An image uses one view; a video can use matching coverage across shots.')+'</p><div class="coverage-grid" role="group" aria-label="Conversation coverage">'+Object.entries(SPCinema.options.coverage).filter(([k])=>state.advanced||['auto','otsa','otsb','two','singlea','reactiona'].includes(k)||state.coverage===k).map(([k,v])=>'<button data-pick="coverage" data-value="'+k+'" aria-pressed="'+(state.coverage===k)+'">'+coverageDiagram(k)+'<strong>'+E(v[0])+'</strong></button>').join('')+'</div>'+(SPCinema.hasCoverage(state)?'<div class="row">'+field('Person A · match your reference name','subjectA',state.subjectA)+field('Person B · match your reference name','subjectB',state.subjectB)+'</div>'+cinemaSelect(state.type==='image'?'Person speaking in this still':'Speaker for entered dialogue','speakerRole')+'<p class="hint">'+(state.type==='image'?'This chooses a speaking expression in one still.':'Enter exact spoken words in Advanced. Choosing a speaker does not invent dialogue.')+' Identity references still define appearance; these controls define staging.</p>':'')+'<h3>Editable composition examples</h3><div class="pills">'+Object.entries(SPCinema.presets).map(([id,p])=>'<button type="button" data-cinema-preset="'+id+'">'+E(p.name)+'</button>').join('')+'</div><p class="hint">Unconventional wide-angle and foreground examples expose the ingredients behind unusual compositions. They do not promise to reproduce a film.</p>'+(state.advanced?'<div class="cinema-advanced"><span class="advanced-badge">Advanced</span><h3>Filmmaking guidelines</h3>'+cinemaSelect('Conversation axis & eyelines','axisRule')+'<div class="row">'+cinemaSelect('Headroom','headroom')+cinemaSelect('Looking room','lookRoom')+'</div>'+cinemaSelect('Depth layers','depthLayers')+(state.type==='video'&&state.timelineMode==='multi'?cinemaSelect('Coverage cuts','cutRule'):'')+'<p class="hint">Continuity guidance is optional. Deliberate axis crossings and jump cuts are creative choices, not automatic errors. Camera angle and lens controls remain in Advanced controls.</p></div>':'<p class="hint">Advanced reveals all coverage choices, headroom, looking room, depth layers and continuity rules.</p>')+'</details>';}
function previewCinema(id){cinemaPresetChoice=id;presetChoice=null;editPresetChoice=null;const p=SPCinema.presets[id];$('preset-content').innerHTML='<h2 id="preset-title">'+E(p.name)+'</h2><p>This example replaces only the choices listed below. Your scene description, identities, references, output settings and manually edited prompt are kept.</p><dl class="preset-changes">'+Object.entries(p.settings).map(([k,v])=>'<div><dt>'+E(k.replace(/([A-Z])/g,' $1'))+'</dt><dd>'+E(SPCinema.options[k]?.[v]?.[0]||SP.cameraOptions[k]?.[v]?.[0]||SP.categories[v]?.[0]||v)+'</dd></div>').join('')+'</dl><p class="hint">All choices are editable. This is a composition recipe, not a recreation of a named film.</p>';$('preset-dialog').showModal();}

let contentPreviewState=null,contentUndo=null;
function contentControls(){if(!SP.isCreative(state))return '';const p=SPContent.selected(state),f=SPContent.family(state),fk=SPContent.familyKey(state),vk=SPContent.variantKey(state);return '<section class="block content-controls" id="content-controls"><h2>What is this for?</h2><p class="hint">Choose a content format, then refine it. Your scene and references stay yours.</p>'+SPWorkflow.picker(state,E)+'<details class="format-list-selectors"><summary>Use list selectors</summary>'+sel('Content format',fk,Object.keys(SPContent.available[state.type]).map(k=>[k,SPContent.families[k]]),f)+(p?sel('Format variation',vk,[['auto','Suggested · '+SPContent.variants[f][SPContent.available[state.type][f][0]].label],...SPContent.available[state.type][f].map(k=>[k,SPContent.variants[f][k].label])],state[vk]):'')+'</details>'+(p?''+'<p class="format-caption">'+E(p.instruction)+'</p><div class="mini-actions"><button id="preview-content">Preview a starting example</button><button id="content-refs">Map product &amp; creator</button></div><p class="hint">Selecting a format adds guidance; it does not replace your description. Preview an example to replace the scene and camera choices explicitly.</p><details class="content-brief"><summary>Product, setting &amp; message <small>Optional brief details</small></summary>'+field('Product name','productName',state.productName,false,'e.g. sleeveless green midi dress')+field('Product details to preserve','productDetails',state.productDetails,true,'Shape, colors, fabric, label or packaging details')+field('Setting','contentSetting',state.contentSetting,false,'e.g. bright bedroom with an uncluttered background')+field('Main message / supplied benefit','contentMessage',state.contentMessage,true,'Only include claims you want in the prompt')+(p.key==='before'?field('Before state','contentBefore',state.contentBefore,true)+field('After state','contentAfter',state.contentAfter,true):'')+(['ads','poster'].includes(f)?field('Exact headline (optional)','contentHeadline',state.contentHeadline)+field('Exact call to action (optional)','contentCTA',state.contentCTA):'')+(f==='product'?field('Actual dimensions / exact callouts','contentCallouts',state.contentCallouts,true,'e.g. Height: 20 cm; width: 8 cm. Never inferred.'):'')+'<p class="hint">Text rendering can need correction. Check your publishing requirements and add final typography separately when precision matters.</p></details><details class="content-help"><summary>How this maps to Marketing Studio</summary><p>Choose Marketing Studio in “Where will you use it?” to see its setup guide. Product and Avatar are separate destination fields. ShotPrompt does not upload or bind assets.</p>'+SPContent.sources.map(([label,url])=>'<p><a href="'+url+'" target="_blank" rel="noopener noreferrer">'+label+'</a></p>').join('')+'<p class="hint">Our editable recipes are based on public guidance, not hidden preset instructions. TikTok is a content category, not a generation model.</p></details>':'')+(contentUndo?'<button id="undo-content">Undo content example</button>':'')+'</section>';}
function renderContentMapping(){let box=$('content-mapping');if(!box){box=document.createElement('div');box.id='content-mapping';$('mapping').after(box);}const wasOpen=!!box.querySelector('details')?.open;const marketing=state.model.startsWith('marketing');box.hidden=!SPContent.active(state)&&!marketing;if(box.hidden)return;const maps=SPContent.mapping(state);box.innerHTML='<details class="content-map"'+(wasOpen?' open':'')+'><summary>Product &amp; creator setup</summary><p class="hint">'+(state.draft!==null?'Builder mapping; your manual output is kept. ':'')+'Attach these references in the destination. Marketing Studio uses separate Product and Avatar selections.</p>'+maps.map(m=>'<p><strong>'+E(m.slot)+'</strong> · '+E(m.name)+' ← '+E(m.label)+' ('+E(m.role)+')</p>').join('')+(!maps.some(m=>m.slot==='Product')?'<p>Product: not mapped yet. Add a Product or Outfit reference.</p>':'')+(!maps.some(m=>m.slot==='Avatar')?'<p>Avatar: add an Identity reference when a specific creator is needed.</p>':'')+'<button type="button" data-review-field="refs">Review references</button></details>';}
function previewContent(){contentPreviewState=SPContent.example(state);const skip=new Set(['refs','beats','draft','views']);const changes=Object.keys(contentPreviewState).filter(k=>!skip.has(k)&&JSON.stringify(state[k])!==JSON.stringify(contentPreviewState[k]));$('content-preview').innerHTML='<h2 id="content-preview-title">'+E(SPContent.selected(state).label)+' starting example</h2><p>This replaces the choices below. Your product brief, references, selected destination, extra instructions and manual output are kept. Timed plans are parked unless this example needs multiple shots. Review any retained instructions for conflicts.</p><dl class="preset-changes">'+changes.map(k=>'<div><dt>'+E(k.replace(/([A-Z])/g,' $1'))+'</dt><dd>'+E(contentPreviewState[k])+'</dd></div>').join('')+'</dl>'+(contentPreviewState.timelineMode==='multi'?'<p>Two timed shots: the before state, then the after state. Replace these placeholders with your actual states.</p>':'');$('content-dialog').showModal();}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.id==='preview-content')previewContent();if(b.id==='cancel-content')$('content-dialog').close();if(b.id==='apply-content'&&contentPreviewState){contentUndo=JSON.parse(JSON.stringify(state));state=contentPreviewState;contentPreviewState=null;$('content-dialog').close();render();toast(state.draft!==null?'Builder example applied. Your edited output is kept.':'Example applied. Make the details yours.');}if(b.id==='undo-content'&&contentUndo){state=contentUndo;contentUndo=null;render();toast('Previous choices restored.');}if(b.id==='content-refs')reviewField('refs');});

function render(){SPWorkflow.capture();const video=state.type==='video',sheet=state.type==='sheet';
document.querySelectorAll('[data-type]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.type===state.type));$('simple').setAttribute('aria-pressed',!state.advanced);$('advanced').setAttribute('aria-pressed',state.advanced);
$('heading').textContent=({image:'Start with the picture in your head.',video:'Give your idea a little movement.',sheet:'One character. Every side.'})[state.type];$('subtitle').textContent='Pick what feels right. We’ll put it into prompt language.';if(SPEdit.active(state)){$('heading').textContent=state.type==='video'&&state.videoTask==='extend'?'Continue from where you left off.':'Change the details. Keep what matters.';$('subtitle').textContent='Choose your source, describe the change, and review what stays.';}
const kind=video?'video':'image';if(SP.profiles[state.model].kind!==kind){state.model=kind==='video'?(state.videoTask==='new'?'seedance':'seedance25'):'seedream';state.draft=null;}
if(video&&state.videoTask!=='new')state.model='seedance25';if(!SP.isCreative(state)&&state.model.startsWith('marketing'))state.model=video?'seedance25':'seedream';$('model').innerHTML=Object.entries(SP.profiles).filter(([k,p])=>(p.kind===kind)&&(!k.startsWith('marketing')||SP.isCreative(state))&&!(video&&state.videoTask!=='new'&&k!=='seedance25')).map(([k,p])=>'<option value="'+k+'"'+(k===state.model?' selected':'')+'>'+E(p.name)+'</option>').join('');$('model').disabled=false;
let html='';
if(SP.isCreative(state))html+=contentControls()+'<details class="content-scene-settings"><summary>Scene category &amp; visual guides</summary>'+(SPContent.active(state)?'':startingPoints())+visualGuide()+sceneChoices()+'</details>';
if(video)html+='<div class="block"><h2>What are you making?</h2><div class="pills" role="group" aria-label="Video task">'+[['new','A new video'],['edit','Edit a video'],['extend','Extend a video']].map(([k,label])=>'<button data-pick="videoTask" data-value="'+k+'" aria-pressed="'+(state.videoTask===k)+'">'+label+'</button>').join('')+'</div><p class="hint">Video edit and extension prompts use Seedance 2.5. Attach the source video in your generation app and select its corresponding mode.</p></div>';if(state.type==='image')html+='<div class="block"><h2>What are you making?</h2><div class="pills" role="group" aria-label="Image task"><button data-pick="task" data-value="new" aria-pressed="'+(state.task==='new')+'">A new image</button><button data-pick="task" data-value="edit" aria-pressed="'+(state.task==='edit')+'">Edit an image</button></div></div>';

if(SPEdit.active(state))html+='<div class="edit-source-intro"><span class="edit-step">1 · SOURCE</span><h2>'+(state.type==='image'?'Choose the image to edit':'Choose the source video')+'</h2><p class="hint">'+(state.type==='image'?'The first uploaded-image reference is the edit target. Move references Earlier/Later to change that target.':'Map exactly one source video. Other references can guide identity, outfits or locations.')+' ShotPrompt maps your source; attach the actual media in the destination editor.</p></div>'+refs()+editStartingPoints();
if(video&&state.videoTask!=='new'){html+='<div class="block"><h2>'+ (state.videoTask==='edit'?'Describe the video edit':'Continue from the final frame')+'</h2>'+(state.videoTask==='edit'?editFields():(SPTiming.active(state)?'<p class="hint">Plan the continuation in Timing &amp; shots below. The whole-clip action is kept for when timing is off.</p>':field('What happens next?','action',state.action,true))+'<label for="duration">Extension length in seconds</label><input id="duration" data-key="duration" type="number" min="4" max="30" value="'+state.duration+'">')+'<p class="hint">'+(state.videoTask==='edit'?'The source duration, aspect ratio, camera motion and sound are preserved by default.':'The extension follows the source aspect ratio and continues its established camera motion and sound.')+'</p></div>';
}else{if(!(state.type==='image'&&state.task==='edit'))html+='<div class="block"><h2>'+ (sheet?'Who is your character?':'What do you imagine?')+'</h2><label class="sr-only" for="idea">Your visual idea</label><textarea id="idea" data-key="'+(sheet?'sheetIdea':'idea')+'" placeholder="Describe it in your own words…">'+E(sheet?state.sheetIdea:state.idea)+'</textarea><p class="hint">'+(sheet?'Describe the face, hair, body and one outfit. Use a reference below to keep the identity.':'You don’t need camera vocabulary. Start with who, where and what happens.')+'</p>'+(!sheet?'<button id="cafe-example">Try a scene example</button>':'')+'</div>';
if(SP.isCreative(state))html+=sceneFields();
if(sheet){const l=SP.sheetLayout(state);let active=0;html+='<div class="block"><h2>Choose your panels</h2><p class="hint">Choose None to remove a slot. The remaining views are packed into '+l.count+' equal '+(l.count===1?'cell':'cells')+'; no blank panels are requested.</p><div class="pills" role="group" aria-label="Number of views">'+[1,2,3,4].map(n=>'<button data-panel-count="'+n+'" aria-pressed="'+(l.count===n)+'">'+n+(n===1?' view':' views')+'</button>').join('')+'</div><div class="panel-grid panel-slots">'+state.views.map((v,i)=>{const pos=v==='None'?'omitted':l.positions[active++];return '<div class="panel'+(v==='None'?' omitted':'')+'">'+(v==='None'?'<div class="empty-panel">No output panel</div>':sheetIcon(v))+'<label for="view-'+i+'">Slot '+(i+1)+' · '+pos+'</label><select id="view-'+i+'" data-view="'+i+'">'+options(['None','Front','Left profile','Back','Right profile','Face close-up'].map(x=>[x,x]),v)+'</select></div>';}).join('')+'</div><h3 style="margin-top:22px">The layout you are requesting</h3><div class="layout-preview" style="grid-template-columns:repeat('+l.columns+',1fr)">'+l.views.map((v,i)=>'<div><strong>'+E(v)+'</strong><small>Cell '+(i+1)+' · '+l.positions[i]+'</small></div>').join('')+'</div><p class="hint">'+(l.count?'Every cell has equal dimensions. A face close-up stays inside its own cell.':'Choose at least one view to compose a prompt.')+'</p>'+sel('Output method','sheetOutput',[['grid','One image with the selected panels'],['separate','Separate prompt for each view']],state.sheetOutput)+'<p class="hint">If the model keeps adding a large portrait, try separate prompts. Paste one prompt at a time to request one view per image. ShotPrompt does not generate or combine images.</p></div>';} else{if(state.type==='image'&&state.task==='edit'){html+='<div class="block"><h2>Describe the edit</h2>'+editFields()+'<p class="hint">Attach your base image as the first image reference below. Original dimensions are preserved; new-image framing and light presets are not applied.</p></div>';}else if(!(video&&SPTiming.active(state)))html+=framing();if(video)html+=timingControls()+(SPTiming.active(state)?'':movements()+ '<div class="block"><h2>What does the subject do?</h2>'+field('Action over the whole clip','action',state.action,true)+ '<div class="row"><div><label for="duration">Length in seconds</label><input id="duration" type="number" min="1" max="300" data-key="duration" value="'+state.duration+'"></div>'+sel('Image shape','ratio',['16:9','9:16','1:1','4:3','3:4'].map(x=>[x,x]),state.ratio)+'</div></div>');
if(!(state.type==='image'&&state.task==='edit'))html+='<div class="block"><h2>Choose the light and feeling</h2><label>Light</label>'+pills('light',{night:'Night practicals',warm:'Warm afternoon',soft:'Soft morning',day:'Clean daylight',studio:'Soft studio'})+'<label style="margin-top:20px">Feeling</label>'+lookChoices()+'</div>';}}
if(video&&state.videoTask==='extend')html+=timingControls();
html+=effects()+(SPEdit.active(state)?'':refs());
if(!video&&!(state.type==='image'&&state.task==='edit'))html+='<div class="block">'+sel('Image shape','ratio',['16:9','9:16','1:1','4:3','3:4','3:2','2:3'].map(x=>[x,x]),state.ratio)+'</div>';
if(state.advanced){html+='<div class="block advanced-controls" id="advanced-controls"><h2>Advanced controls <span class="advanced-badge">Advanced</span></h2><p class="hint">These are the extra controls revealed by Advanced mode. Their contribution appears beside the prompt.</p>'+(SP.isCreative(state)?'<button type="button" data-review-field="axisRule">Open highlighted composition rules</button>':'')+cinemaControls()+creativeAdvanced()+(SP.isCreative(state)?cinemaSelect('Image-wide finish','surface'):'')+field('Extra instructions','extra',state.extra,true,'What must stay the same? What should change?')+field('Avoid (where supported)','negative',state.negative,false,'e.g. logos, text overlays')+((video&&state.videoTask==='new')?field('Sound and music','audio',state.audio)+field('Speaker','speaker',state.speaker)+field('Exact spoken words (optional)','dialogue',state.dialogue,true):'')+'<p class="hint">Hidden advanced settings stay active in Simple mode. '+(state.extra||state.negative||state.dialogue?'You have active advanced instructions.':'')+'</p></div>';}
if(!state.advanced&&(state.extra||state.negative||state.dialogue))html+='<div class="help">Advanced instructions are active. Switch to Advanced to review them.</div>';
$('editor').innerHTML=html;SPWorkflow.layout(state);$('migration-note').hidden=!retiredRaw;document.querySelector('.workspace').classList.toggle('advanced-mode',state.advanced);$('advanced').disabled=false;$('simple').disabled=false;$('mode-explainer').innerHTML=state.advanced?'Advanced is on. <a href="#advanced-controls">Jump to the highlighted extra controls</a>. Simple choices remain available.':'Simple shows the visual essentials. Advanced adds extra instructions, exclusions'+((video&&state.videoTask==='new')?', sound and dialogue':'')+'.';update();}

function renderReview(issues){
$('checks').innerHTML='<h3>Prompt review</h3>'+(state.draft!==null?'<p class="review-note">Builder checks refer to your saved choices. Edited-output checks inspect your text. Nothing is changed automatically.</p>':'')+(issues.length?'<strong>Review '+issues.length+' '+(issues.length===1?'item':'items')+'</strong><ul>'+issues.map(w=>'<li><span class="review-scope">'+(w.scope==='output'?'Edited output':'Builder')+'</span><p>'+E(w.message)+'</p>'+(w.evidence?'<small class="review-evidence">Matched: “'+E(String(w.evidence).slice(0,180))+'”</small>':'')+'<button type="button" class="review-link" data-review-field="'+E(w.field||SPReview.locations[w.code]||'output')+'">Review '+E((w.field||SPReview.locations[w.code]||'output').replace(/([A-Z])/g,' $1'))+'</button></li>').join('')+'</ul>':'<p class="ok">No conflicts found by the basic checks.</p>')+'<p class="review-note">English text rules flag possible conflicts. They cannot inspect reference images or guarantee the generated result.</p>';
}
function renderDestination(){
const d=SPReview.destination(state);if(SP.isCreative(state))d.notes.push('Coverage, eyelines, continuity rules and rendering style are written directions. They do not replace identity references or guarantee staging across generated shots.');$('destination-caption').textContent=d.alibaba?'Alibaba Cloud · prompt and API settings':d.comfy?'ComfyUI · prompt and workflow setup':'Prompt and app settings';
const list=a=>'<ul>'+a.map(x=>'<li>'+E(x)+'</li>').join('')+'</ul>';
$('destination-guide').innerHTML='<h3>Included in the text</h3>'+list(d.sent)+'<h3>Set separately</h3>'+list(d.separate)+(d.notes.length?'<h3>For this profile</h3>'+list(d.notes):'')+(d.facts?'<div class="catalog-facts"><strong>'+E(d.facts.model)+'</strong><p>Listed ratios: '+E(d.facts.ratios)+'</p>'+(d.facts.duration?'<p>Duration: '+E(d.facts.duration)+'</p>':'')+d.facts.options.map(x=>'<p>'+E(x)+'</p>').join('')+'</div>':'')+'<p class="hint">'+E(d.checked)+' The builder offers a subset of available controls. Writing a value does not set the destination app.</p>'+(state.model==='qwen'?'<a href="https://docs.comfy.org/tutorials/image/qwen/qwen-image-2-1" target="_blank" rel="noopener noreferrer">Official Qwen workflow guide</a>':state.model==='flux'?'<a href="https://help.bfl.ai/articles/7734566352-does-flux-2-support-negative-prompting" target="_blank" rel="noopener noreferrer">FLUX.2 negative-prompt guidance</a>':'');
}
function reviewField(key){if(key.startsWith('content')||['productName','productDetails'].includes(key)){document.querySelector('.content-brief')?.setAttribute('open','');}
if(Object.keys(SPCinema.options).includes(key)||['subjectA','subjectB'].includes(key)){cinemaOpen=true;if(key==='renderStyle'&&!['render','anime','illustration'].includes(state.style))state.style=['watercolor','ink','halftone','collage'].includes(state.renderStyle)?'illustration':'render';if(!['renderStyle'].includes(key))state.advanced=true;render();}
const advancedKeys=['angle','lens','focus','composition','direction','speed','intensity','timing','extra','negative','audio','dialogue','speaker'];
if(advancedKeys.includes(key)&&!state.advanced){state.advanced=true;render();}
let el=key==='timing'?$('timing-controls'):key==='refs'?$('references'):key==='output'?$('output'):key==='model'?$('model'):key==='views'?document.querySelector('[data-view]'):['shot','light','move','style'].includes(key)?document.querySelector('[data-pick="'+key+'"][aria-pressed="true"]'):$('f-'+key)||$(key);
if(!el)el=$('output');SPWorkflow.reveal(el);el.scrollIntoView({block:'center'});el.focus({preventScroll:true});
}

let previousCompiled=null,feedbackTimer;
function promptFeedback(compiled){const changed=previousCompiled!==null&&previousCompiled!==compiled;previousCompiled=compiled;if(!changed)return;
const queued=state.draft!==null;const panel=$('prompt-panel');panel.dataset.feedback=queued?'queued':'updated';$('prompt-feedback').textContent=queued?'Builder changed · edited prompt kept. Use updated builder when ready.':'Prompt updated from your choices';clearTimeout(feedbackTimer);feedbackTimer=setTimeout(()=>{delete panel.dataset.feedback;$('prompt-feedback').textContent='';},2600);}
function update(){const compiled=SP.compose(state);promptFeedback(compiled);if(state.draft===null)$('output').value=compiled;else if(document.activeElement!==$('output'))$('output').value=state.draft;$('draftbar').hidden=state.draft===null;$('profile-note').textContent=SP.profiles[state.model].note;$('wordcount').textContent=$('output').value.trim().split(/\s+/).filter(Boolean).length+' words';const issues=SPReview.collect(state,$('output').value);renderReview(issues);renderDestination();renderEditSummary();renderTimingHandoff();$('mapping').innerHTML=(state.refs.length?'<h3>Reference mapping</h3><p class="hint">'+(state.draft===null?'Upload numbered images and videos in this order. Bind Elements separately using their exact mentions.':'Builder mapping only: your manually edited output is unchanged. Rebuild it before using this order.')+'</p>':'')+state.refs.map((r,i)=>'<p><strong>'+E(r.kind==='element'?r.token||'(missing Element token)':SP.refName(state,i))+'</strong> → '+E(r.name||'subject')+' · '+E(r.role)+'</p>').join('');document.querySelectorAll('[data-ref-title]').forEach(el=>{const i=+el.dataset.refTitle;if(state.refs[i])el.textContent=refTitle(state.refs[i],i);});advancedSummary();renderContentMapping();SPWorkflow.refresh(state);persist();}
document.addEventListener('input',e=>{const t=e.target;if(t.dataset.key||t.id==='output'||t.dataset.beat!==undefined||t.dataset.ref!==undefined){contentUndo=null;$('undo-content')?.remove();}if(t.dataset.beat!==undefined){clearPresetUndo();const b=state.beats[+t.dataset.beat];if(b){b[t.dataset.beatKey]=t.type==='number'?Math.max(0,Math.min(300,Number(t.value)||0)):t.value;update();}return;}if(t.id==='output'||t.dataset.key||t.dataset.ref!==undefined)clearPresetUndo();if(t.id==='output'){state.draft=t.value;update();return;}if(t.dataset.key){state[t.dataset.key]=t.type==='number'?Math.max(1,Math.min(300,Number(t.value)||1)):t.value;update();}if(t.dataset.ref!==undefined&&t.tagName!=='SELECT'){state.refs[+t.dataset.ref][t.dataset.refKey]=t.value;update();}});
document.addEventListener('change',async e=>{const t=e.target;if(t.dataset.beat!==undefined&&t.tagName==='SELECT'){clearPresetUndo();state.beats[+t.dataset.beat][t.dataset.beatKey]=t.value;if(t.dataset.beatKey==='move')state.beats[+t.dataset.beat].direction='default';render();return;}if(t.id==='model'||t.id==='import'||t.dataset.key||t.dataset.ref!==undefined||t.dataset.view!==undefined)clearPresetUndo();if(t.id==='model'){state.model=t.value;render();}if(t.dataset.key&&t.tagName==='SELECT'){if(['contentImage','contentVideo'].includes(t.dataset.key))state[SPContent.variantKey(state)]='auto';state[t.dataset.key]=t.value;if(['sheetOutput','effect','contentImage','contentVideo','contentVariantImage','contentVariantVideo',...Object.keys(SPCinema.options)].includes(t.dataset.key))render();else update();}if(t.dataset.ref!==undefined&&t.tagName==='SELECT'){const r=state.refs[+t.dataset.ref];r[t.dataset.refKey]=t.value;if(t.dataset.refKey==='kind'){if(t.value!=='image'&&thumbs.has(+t.dataset.ref)){URL.revokeObjectURL(thumbs.get(+t.dataset.ref));thumbs.delete(+t.dataset.ref);}if(t.value==='video')r.role='source';else if(r.role==='source')r.role='identity';}render();}if(t.dataset.view!==undefined){state.views[+t.dataset.view]=t.value;render();}if(t.dataset.preview!==undefined&&t.files[0]){const f=t.files[0];if(!/^image\/(png|jpeg|webp)$/.test(f.type)||f.size>15e6){toast('Choose a PNG, JPEG or WebP smaller than 15 MB.');return;}const i=+t.dataset.preview;if(thumbs.has(i))URL.revokeObjectURL(thumbs.get(i));thumbs.set(i,URL.createObjectURL(f));render();toast('Preview added locally. Attach this image separately in your generation app.');}if(t.id==='import'&&t.files[0]){try{if(t.files[0].size>2e6)throw Error('Project file must be smaller than 2 MB.');const next=SP.validate(JSON.parse(await t.files[0].text()));state=next;clearThumbs();render();toast('Project opened. Reattach local preview images if needed.');}catch(e){toast(e.message);}t.value='';}});
document.addEventListener('toggle',e=>{const t=e.target;if(t.id==='visual-guide'&&t.isConnected)guideOpen=t.open;if(t.id==='cinema-controls'&&t.isConnected)cinemaOpen=t.open;if(t.matches?.('details[data-ref-card]')&&t.isConnected){const r=state.refs[+t.dataset.refCard];if(r){if(t.open)expandedRefs.add(r);else expandedRefs.delete(r);}}},true);
function jumpTo(id){if(id==='prompt-panel'){SPWorkflow.go('prompt');return;}const el=$(id);SPWorkflow.reveal(el);(id==='prompt-panel'?$('output'):el).scrollIntoView({block:'center'});el.focus({preventScroll:true});}
function clearThumbs(){thumbs.forEach(u=>URL.revokeObjectURL(u));thumbs.clear();}
document.addEventListener('click',e=>{const t=e.target.closest('button');if(!t)return;
if(t.dataset.formatFamily||t.dataset.formatVariant){clearPresetUndo();contentUndo=null;state[SPContent.familyKey(state)]=t.dataset.formatFamily||SPContent.family(state);state[SPContent.variantKey(state)]=t.dataset.formatVariant||'auto';render();const chosen=t.dataset.formatFamily?document.querySelector('.variant-cards [aria-pressed="true"]')||document.querySelector('.format-browser>summary'):$(t.id);SPWorkflow.reveal(chosen);chosen?.focus({preventScroll:true});return;}
if(t.dataset.timingMode){clearPresetUndo();state=SPTiming.initialize(state,t.dataset.timingMode);render();return;}
if(t.id==='fit-beats'){clearPresetUndo();state=SPTiming.fit(state);render();toast('Ranges fitted to duration. Descriptions are kept.');return;}
if(t.id==='add-beat'){clearPresetUndo();const start=state.beats.at(-1)?.end||0;if(state.beats.length<12)state.beats.push(SPTiming.make(state,start,Math.min(300,start+2)));render();return;}
if(t.dataset.beatRemove!==undefined){clearPresetUndo();state.beats.splice(+t.dataset.beatRemove,1);render();return;}
if(t.dataset.beatShift!==undefined){clearPresetUndo();const i=+t.dataset.beatShift,j=i-1;if(j>=0)[state.beats[i],state.beats[j]]=[state.beats[j],state.beats[i]];render();return;}
if(t.dataset.reviewField){reviewField(t.dataset.reviewField);return;}
if(t.dataset.editPreset){cinemaPresetChoice=null;previewEdit(t.dataset.editPreset);return;}
if(t.dataset.previewPreset){cinemaPresetChoice=null;editPresetChoice=null;previewPreset(t.dataset.previewPreset);return;}
if(t.id==='cancel-preset'){$('preset-dialog').close();return;}
if(t.dataset.cinemaPreset){previewCinema(t.dataset.cinemaPreset);return;}
if(t.id==='apply-preset'&&cinemaPresetChoice){presetUndo=JSON.parse(JSON.stringify(state));state=SPCinema.apply(state,cinemaPresetChoice);cinemaPresetChoice=null;cinemaOpen=true;$('preset-dialog').close();render();toast(state.draft===null?'Composition example applied. All choices remain editable.':'Builder composition updated. Your edited prompt is kept.');return;}
if(t.id==='apply-preset'&&editPresetChoice){presetUndo=JSON.parse(JSON.stringify(state));state=SPEdit.apply(state,editPresetChoice);editPresetChoice=null;$('preset-dialog').close();render();toast(state.draft===null?'Editing example applied. Adapt its details to your source.':'Builder instructions updated. Your edited output is kept.');return;}
if(t.id==='apply-preset'&&presetChoice){presetUndo=JSON.parse(JSON.stringify(state));state=SPGuide.apply(state,presetChoice);$('preset-dialog').close();render();toast(state.draft===null?'Preset applied. Every choice is editable.':'Preset applied to builder. Your edited prompt is kept; rebuild when ready.');return;}
if(t.id==='undo-preset'&&presetUndo){state=presetUndo;presetUndo=null;render();toast('Previous builder choices restored.');return;}
if(t.dataset.guideTopic){guideTopic=t.dataset.guideTopic;document.querySelectorAll('[data-guide-topic]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.guideTopic===guideTopic));$('guide-content').innerHTML=guideContent();return;}
if(t.dataset.type||t.dataset.pick||t.dataset.panelCount||t.id==='cafe-example'||t.id==='rebuild'||t.id==='add-ref'||t.dataset.removeRef!==undefined||t.dataset.refShift!==undefined)clearPresetUndo();
if(t.dataset.type){state.type=t.dataset.type;state.draft=null;render();}if(t.dataset.pick){if(t.dataset.pick==='style'&&t.dataset.value!==state.style&&['render','anime','illustration'].includes(state.style))state.renderStyle='auto';state[t.dataset.pick]=t.dataset.value;if(t.dataset.pick==='move')state.direction='default';if(t.dataset.pick==='coverage')cinemaOpen=true;render();}if(t.id==='simple'||t.id==='advanced'){state.advanced=t.id==='advanced';render();if(state.advanced){SPWorkflow.reveal($('advanced-controls'));document.getElementById('advanced-controls')?.scrollIntoView({block:'start'});}}if(t.dataset.panelCount){const n=+t.dataset.panelCount,chosen=SP.activeViews(state).slice(0,n);for(const v of ['Front','Left profile','Back','Right profile','Face close-up'])if(chosen.length<n&&!chosen.includes(v))chosen.push(v);state.views=chosen.concat(Array(Math.max(0,4-n)).fill('None'));render();}if(t.id==='rebuild'){state.draft=null;render();}if(t.id==='cafe-example'){const ex=sceneExamples[state.category];state.idea=ex[0];state.action=ex[1];state.audio=ex[2];render();toast('Scene example applied. Your other choices are kept.');}if(t.id==='add-ref'){state.refs.push({kind:state.type==='video'&&state.videoTask!=='new'?'video':'image',role:state.type==='video'&&state.videoTask!=='new'||state.type==='image'&&state.task==='edit'?'source':'identity',name:'',token:''});expandedRefs.add(state.refs[state.refs.length-1]);render();SPWorkflow.reveal($('references'));document.querySelector('[data-ref-card="'+(state.refs.length-1)+'"]')?.scrollIntoView({block:'nearest'});}if(t.dataset.refShift!==undefined){const i=+t.dataset.refShift,j=i+ +t.dataset.direction;if(j>=0&&j<state.refs.length){[state.refs[i],state.refs[j]]=[state.refs[j],state.refs[i]];const a=thumbs.get(i),b=thumbs.get(j);thumbs.delete(i);thumbs.delete(j);if(a)thumbs.set(j,a);if(b)thumbs.set(i,b);render();toast(state.draft===null?'Reference order updated. Match this order in your generation app.':'Builder order changed. Your edited prompt is unchanged; rebuild it to use the new mapping.');}}if(t.dataset.removeRef!==undefined){const removed=+t.dataset.removeRef;state.refs.splice(removed,1);if(thumbs.has(removed))URL.revokeObjectURL(thumbs.get(removed));const kept=[...thumbs.entries()].filter(([i])=>i!==removed);thumbs.clear();kept.forEach(([i,u])=>thumbs.set(i>removed?i-1:i,u));render();}if(t.id==='download-retired'&&retiredRaw)download('archived-writing-project.json',retiredRaw,'application/json');if(t.id==='dismiss-migration')$('migration-note').hidden=true;if(t.id==='view-prompt')jumpTo('prompt-panel');if(t.id==='back-builder')jumpTo('editor');if(t.id==='copy'||t.id==='quick-copy')copy();if(t.id==='download')download('shotprompt.txt',$('output').value,'text/plain');if(t.id==='open-project')$('import').click();if(t.id==='export')download('shotprompt-project.json',JSON.stringify(state,null,2),'application/json');});
function download(name,text,mime){const u=URL.createObjectURL(new Blob([text],{type:mime+';charset=utf-8'})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
async function copy(){try{await navigator.clipboard.writeText($('output').value);toast('Prompt copied');}catch(e){$('output').focus();$('output').select();try{if(!document.execCommand('copy'))throw Error();toast('Prompt copied');}catch(e){toast('Text selected. Press Ctrl+C or Command+C to copy.');}}}
function sheetIcon(view){if(view==='Face close-up')return icon('close','static',view);const nose=view==='Left profile'?'<path d="M77 12l-6 7h6"/>':view==='Right profile'?'<path d="M83 12l6 7h-6"/>':view==='Back'?'':'<path d="M77 16h1m5 0h1"/>';return '<svg viewBox="0 0 160 110" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2.3" stroke-linecap="round"><circle cx="80" cy="17" r="10"/>'+nose+'<path d="M68 32q12-10 24 0l5 29-10 3H73l-10-3z M68 34L57 59 M92 34l11 25 M74 65l-2 33h-9 M86 65l2 33h9"/></svg>';}
function advancedSummary(){const box=$('advanced-summary');const lines=[];if(SP.isCreative(state)){for(const [key,opts] of Object.entries(SPCinema.options))if(key!=='renderStyle'&&state[key]!=='auto')lines.push(opts[state[key]][0]);for(const key of ['angle','lens','focus','composition'])if(state[key]!=='auto')lines.push(SP.cameraOptions[key][state[key]][0]);if(state.type==='video'&&!SPTiming.active(state)&&state.move!=='static')lines.push('Camera: '+SP.cameraText(state));if(state.effect!=='none')lines.push('Effect: '+SP.cameraOptions.intensity[state.intensity][0]+(state.type==='video'?' · '+SP.cameraOptions.timing[state.timing][0]:''));}if(state.extra.trim())lines.push('Additional instructions: '+state.extra.trim());if(state.negative.trim())lines.push((['flux','qwen'].includes(state.model)?'Not emitted for this model — avoid: ':'Avoid: ')+state.negative.trim());if(state.type==='video'&&state.videoTask==='new'){lines.push('Audio: '+state.audio);if(state.dialogue.trim())lines.push((SP.isCreative(state)?SPCinema.speaker(state):state.speaker)+' says exactly: '+JSON.stringify(state.dialogue.trim()));else lines.push('No spoken dialogue.');}box.hidden=!state.advanced&&!lines.length;box.innerHTML='<h3>What Advanced adds</h3>'+(state.draft!==null?'<p class="hint">Your manual output is locked. These builder instructions are waiting until you choose Use updated builder.</p>':'')+(lines.length?'<ul>'+lines.map(t=>'<li><mark>'+E(t)+'</mark></li>').join('')+'</ul>':'<p class="hint">Nothing added yet. Fill in the highlighted Advanced controls to add instructions.</p>');}
render();

